public final class TokenBucketTest {
    public static void main(String[] args) {
        checkStartsFullAndDrains();
        checkRefillsOverTime();
        checkRefillCapsAtCapacity();
        System.out.println("all tests passed");
    }

    static void checkStartsFullAndDrains() {
        TokenBucket b = new TokenBucket(3, 1);
        if (!b.allow(0) || !b.allow(0) || !b.allow(0)) throw new AssertionError("expected 3 allows");
        if (b.allow(0)) throw new AssertionError("expected deny once drained");
    }

    static void checkRefillsOverTime() {
        TokenBucket b = new TokenBucket(3, 1);
        for (int i = 0; i < 3; i++) b.allow(0);
        if (b.allow(0.5)) throw new AssertionError("expected deny at t=0.5");
        if (!b.allow(1.0)) throw new AssertionError("expected allow at t=1.0");
        if (b.allow(1.0)) throw new AssertionError("expected deny again immediately after");
    }

    static void checkRefillCapsAtCapacity() {
        TokenBucket b = new TokenBucket(2, 1);
        b.allow(0);
        b.allow(0);
        if (!b.allow(1000) || !b.allow(1000)) throw new AssertionError("expected 2 tokens after long idle");
        if (b.allow(1000)) throw new AssertionError("expected refill capped at capacity");
    }
}

